+    fn hash_at_indexes<F: FnMut(u64)>(&self, hash_indexes: &[u64], mut f: F) {
+        // Same as `slice_hash` per index, but hashes four indexes per pass over the slice.
+        const FNV_PRIME: u64 = 0x100000001b3;
+        let slice = self.as_ref();
+        let mut chunks = hash_indexes.chunks_exact(4);
+        for chunk in &mut chunks {
+            let mut h = [chunk[0], chunk[1], chunk[2], chunk[3]];
+            for &byte in slice {
+                for x in &mut h {
+                    *x = (*x ^ u64::from(byte)).wrapping_mul(FNV_PRIME);
+                }
+            }
+            h.into_iter().for_each(&mut f);
+        }
+        for k in chunks.remainder() {
+            f(slice_hash(slice, *k));
+        }
+    }
+}

